"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/blog-pages/variants/01-index";
import View1 from "./components/blog-pages/variants/02-rounded-index";
const variants = {"index":View0,"rounded-index":View1};
export interface ArtemisBlogIndexProps { className?: string; variant?: "index" | "rounded-index"; }
export function ArtemisBlogIndex({ className, variant = "index" }: ArtemisBlogIndexProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
